<script lang="ts">
  import type {FieldDefinition,ModuleDefinition,JsonValue} from '../../api/domain';
  import {loadModuleSchema} from '../../api/workspace';
  import ConditionGroupBuilder from './ConditionGroupBuilder.svelte';
  import type {ConditionGroup} from '../../util/formRules';
  let {kind,config=$bindable({}),modules,fields,moduleUid=''}:{kind:string;config:Record<string,JsonValue>;modules:ModuleDefinition[];fields:FieldDefinition[];moduleUid?:string}=$props();
  let targetFields=$state<FieldDefinition[]>([]);let error=$state('');
  let incomingFields=$state<FieldDefinition[]>([]);
  const incoming=$derived(kind==='rollup'&&config.direction==='incoming');
  const relationships=$derived(fields.filter(f=>f.active&&f.field_type==='relationship'));
  const target=$derived(kind==='relationship'?String(config.target_module_uid||''):String(relationships.find(f=>f.key===config.relationship_field)?.config.target_module_uid||''));
  const mappings=$derived((Array.isArray(config.auto_fill)?config.auto_fill:[]) as {source_field:string;target_field:string}[]);
  const destinations=$derived(fields.filter(f=>f.active&&['text','long_text','select','integer','decimal','date','boolean'].includes(f.field_type)));
  function compatible(key:string,target:string){const field=targetFields.find(f=>f.key===key);const source=field?.field_type==='formula'&&field.config.result_type==='text'?'text':field?.field_type||'';if(['text','long_text','select'].includes(target))return ['text','long_text','select'].includes(source);if(target==='integer')return ['integer','auto_number'].includes(source);if(target==='decimal')return ['integer','auto_number','decimal','formula'].includes(source);return ['date','boolean'].includes(target)&&source===target;}
  function changeMapping(index:number,key:'source_field'|'target_field',value:string){config={...config,auto_fill:mappings.map((mapping,i)=>i===index?{...mapping,[key]:value,...(key==='source_field'?{target_field:''}:{})}:mapping)};}
  $effect(()=>{const uid=target;let disposed=false;targetFields=[];error='';if(uid)void loadModuleSchema(uid).then(schema=>{if(!disposed)targetFields=schema.fields.filter(f=>f.active&&!['attachments','relationship','lookup','rollup'].includes(f.field_type));}).catch(reason=>{if(!disposed)error=String(reason);});return()=>{disposed=true;};});
  $effect(()=>{const uid=incoming?String(config.source_module_uid||''):'';let disposed=false;incomingFields=[];if(uid)void loadModuleSchema(uid).then(schema=>{if(!disposed)incomingFields=schema.fields.filter(f=>f.active);}).catch(reason=>{if(!disposed)error=String(reason);});return()=>{disposed=true;};});
</script>
<div class="relationship-config">
  {#if kind==='rollup'}<label>Which linked records?<select aria-label="Aggregate direction" value={incoming?'incoming':'outgoing'} onchange={event=>config=event.currentTarget.value==='incoming'?{direction:'incoming',source_module_uid:'',relationship_field:'',function:'sum',target_field:''}:{relationship_field:'',function:'sum',target_field:''}}><option value="outgoing">Records selected in this record</option><option value="incoming">Records in another module that link to this record</option></select></label>{/if}
  {#if incoming}
    <p>For an employee’s used allowance, select Requests and its Employee relationship. MX totals matching, accessible requests—not a running deduction. Edits, cancellations and trash are reflected when refreshed.</p>
    <label>Source module<select aria-label="Aggregate source module" value={String(config.source_module_uid||'')} onchange={event=>config={...config,source_module_uid:event.currentTarget.value,relationship_field:'',target_field:'',filter:null}}><option value="">Choose a module…</option>{#each modules.filter(m=>m.active) as module}<option value={module.uid}>{module.name}</option>{/each}</select></label>
    <label>Relationship back to this module<select aria-label="Incoming relationship" value={String(config.relationship_field||'')} onchange={event=>config={...config,relationship_field:event.currentTarget.value}}><option value="">Choose the linking field…</option>{#each incomingFields.filter(f=>f.field_type==='relationship'&&(!moduleUid||f.config.target_module_uid===moduleUid)) as field}<option value={field.key}>{field.label}</option>{/each}</select></label>
    <label>Calculation<select aria-label="Incoming aggregate calculation" value={String(config.function||'sum')} onchange={event=>config={...config,function:event.currentTarget.value}}>{#each ['sum','count','average','min','max'] as fn}<option value={fn}>{fn}</option>{/each}</select></label>
    {#if config.function!=='count'}<label>Numeric source field<select aria-label="Incoming numeric field" value={String(config.target_field||'')} onchange={event=>config={...config,target_field:event.currentTarget.value}}><option value="">Choose an amount…</option>{#each incomingFields.filter(f=>['integer','decimal','auto_number'].includes(f.field_type)||(f.field_type==='formula'&&f.config.result_type!=='text')) as field}<option value={field.key}>{field.label}</option>{/each}</select></label>{/if}
    <label class="checkbox"><input type="checkbox" checked={!!config.filter} onchange={event=>config={...config,filter:event.currentTarget.checked?{match:'all',conditions:[]}:null}}/>Only include records matching conditions</label>
    {#if config.filter}<ConditionGroupBuilder group={config.filter as unknown as ConditionGroup} fields={incomingFields.filter(f=>['text','long_text','select','integer','decimal','date','boolean'].includes(f.field_type))} onChange={group=>config={...config,filter:group as unknown as JsonValue}}/>{/if}
    <p>For a remaining balance, add a Number formula in this module, such as <code>allowance - used</code>. This is a calculated balance, not an automatic approval or overdraft-prevention workflow. It includes only records you may access.</p>
  {:else if kind==='relationship'}
    <label>Linked module<select value={String(config.target_module_uid||'')} onchange={event=>config={...config,target_module_uid:event.currentTarget.value,label_field:'',auto_fill:[]}}><option value="">Choose a module…</option>{#each modules.filter(m=>m.active) as module}<option value={module.uid}>{module.name}</option>{/each}</select></label>
    <label>Display field<select value={String(config.label_field||'')} onchange={event=>config={...config,label_field:event.currentTarget.value}}><option value="">Choose a display field…</option>{#each targetFields as field}<option value={field.key}>{field.label}</option>{/each}</select></label>
    <label class="checkbox"><input type="checkbox" disabled={mappings.length>0} checked={config.multiple===true} onchange={event=>config={...config,multiple:event.currentTarget.checked}} /> Allow multiple linked records</label>
    <p>Stores stable record IDs. Referenced records cannot be deleted until their active links are removed.</p>
    <fieldset class="auto-fill"><legend>Fill fields automatically</legend><p>Select one linked record to copy its values into these fields. Changing or clearing the selection updates them. You can edit the copied values before saving; saved copies do not follow later source changes.</p>
{#each mappings as mapping,index}<div class="mapping"><label>Linked source field<select aria-label={`Linked source field ${index+1}`} value={mapping.source_field} onchange={event=>changeMapping(index,'source_field',event.currentTarget.value)}><option value="">Choose source…</option>{#each targetFields as field}<option value={field.key}>{field.label}</option>{/each}</select></label><label>Fill this field<select aria-label={`Fill this field ${index+1}`} value={mapping.target_field} onchange={event=>changeMapping(index,'target_field',event.currentTarget.value)}><option value="">Choose destination…</option>{#each destinations.filter(f=>compatible(mapping.source_field,f.field_type)&&!mappings.some((m,i)=>i!==index&&m.target_field===f.key)) as field}<option value={field.key}>{field.label}</option>{/each}</select></label><button class="button small" type="button" aria-label={`Remove auto-fill mapping ${index+1}`} onclick={()=>config={...config,auto_fill:mappings.filter((_,i)=>i!==index)}}>Remove</button></div>{/each}
      <button class="button small" type="button" disabled={!target||config.multiple===true||mappings.length>=64||!destinations.length} onclick={()=>config={...config,auto_fill:[...mappings,{source_field:'',target_field:''}]}}>Add field mapping</button>
      {#if config.multiple===true}<p>Choose a single linked record to enable auto-fill. Use lookups or rollups for multiple records.</p>{/if}
    </fieldset>
  {:else}
    <label>Relationship<select value={String(config.relationship_field||'')} onchange={event=>config={...config,relationship_field:event.currentTarget.value,target_field:''}}><option value="">Choose a relationship…</option>{#each relationships as field}<option value={field.key}>{field.label}</option>{/each}</select></label>
    {#if kind==='rollup'}<label>Calculation<select value={String(config.function||'sum')} onchange={event=>config={...config,function:event.currentTarget.value}}>{#each ['sum','count','average','min','max'] as fn}<option value={fn}>{fn==='average'?'Average':fn==='count'?'Count linked records':fn[0].toUpperCase()+fn.slice(1)}</option>{/each}</select></label>{/if}
    {#if kind==='lookup'||config.function!=='count'}<label>Linked field<select value={String(config.target_field||'')} onchange={event=>config={...config,target_field:event.currentTarget.value}}><option value="">Choose a field…</option>{#each targetFields.filter(f=>kind==='lookup'||['integer','decimal','auto_number','formula'].includes(f.field_type)) as field}<option value={field.key}>{field.label}</option>{/each}</select></label>{/if}
    <p>Read-only and calculated from the linked records you are allowed to access.</p>
  {/if}
  {#if error}<p role="alert">{error}</p>{/if}
</div>
<style>.relationship-config{display:grid;gap:.65rem;grid-column:1/-1;min-width:0}.relationship-config label{min-width:0}p{color:var(--muted);font-size:.8rem;margin:0}p[role=alert]{color:var(--danger)}.auto-fill{display:grid;gap:.65rem;border:1px solid var(--line);border-radius:.5rem;padding:.8rem;min-width:0}.auto-fill legend{font-weight:600;font-size:.85rem}.auto-fill>button{justify-self:start}.mapping{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:.6rem;align-items:end}.mapping select{width:100%;min-width:0}@media(max-width:600px){.mapping{grid-template-columns:minmax(0,1fr)}.mapping button{justify-self:start}}</style>
